const dataWadL1 = '';
const dataWad2024 = '';
const dataWadWebServices = '';

export const questions_wad_l1 = JSON.parse(atob(dataWadL1));

export const questions_wad_2024 = JSON.parse(atob(dataWad2024));

export const questions_wad_iit_2023 = questions_wad_2024.map(q => ({
    ...q,
    id: q.id.replace('wad-2024', 'wad-iit-2023')
}));

export const questions_wad_web_services = JSON.parse(atob(dataWadWebServices));
